interface OrderPublisher { publish(o: Order): Promise<void>; }

class KafkaOrderPublisher implements OrderPublisher {
  constructor(private readonly producer: Producer, private readonly topic: string) {}

  async publish(o: Order): Promise<void> {
    await this.producer.send({ topic: this.topic, messages: [{ value: JSON.stringify(o) }] });
  }
}

